import base64,gzip,json,pathlib,subprocess,sys
root=pathlib.Path('/content/gliner-ab');root.mkdir(exist_ok=True)
payload=json.loads(gzip.decompress(base64.b64decode('')))
for name,content in payload.items():
 target=root/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
def run(cmd):
 r=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);print(r.stdout[-10000:],flush=True);r.check_returncode()
run([sys.executable,'-m','pip','install','-q','gliner2[local]==2.1.0','disentangled-flash==1.1.1','transformers==5.20.2','cmake','ninja'])
print('BOOTSTRAP_DONE',flush=True)
